using FreshFoundation;
using System.Text.Json;
internal static class R9Checks
{
    internal static int Run()
    {
        var results=new List<object>();int failures=0;string folder=Path.Combine(Directory.GetCurrentDirectory(),"synthetic-r9-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
        void Assert(bool ok){if(!ok)throw new Exception("R9 assertion failed");}
        void Reject(Action action){try{action();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}throw new Exception("Expected rejection");}
        void Test(string name,Action action){try{action();results.Add(new{name,status="PASS"});}catch(Exception e){failures++;results.Add(new{name,status="FAIL",error=e.ToString()});}}
        (EditorWorkspace w,DomainEditor d) Open(bool transfer=true,int auxiliary=4,int decorations=3){string path=Path.Combine(folder,Guid.NewGuid()+".bin");File.WriteAllBytes(path,WorkspaceSyntheticSamples.Slot(transferFixture:transfer,auxiliaryCount:auxiliary,decorationCount:decorations));var w=new EditorWorkspace();w.Open(path);return(w,new(w));}
        void ExactExport(EditorWorkspace w){string output=Path.Combine(folder,Guid.NewGuid()+".bin");var expected=w.Document!.Structure.CopyPayload();foreach(var e in w.Document.Structure.Events.Select((v,i)=>(v,i)).Where(e=>e.v.DataCoordinate!=null&&e.v.Width!=null))w.PrimitiveBytes(e.i)!.CopyTo(expected,e.v.DataCoordinate!.Value-12);var receipt=w.Export(output,folder);var check=Document.Inspect(File.ReadAllBytes(receipt.OutputPath));Assert(expected.SequenceEqual(check.Structure.CopyPayload()));}
        Test("split move merge preserve totals/count/unknown bytes and single undo",()=>{var(w,d)=Open();d.TransferItem(0,1,3);Assert(d.Inventory()[0].Quantity==7&&d.Inventory()[1].Quantity==3&&d.Inventory().Sum(i=>i.Quantity)==14&&d.Inventory().Count==3);ExactExport(w);w.Undo();Assert(w.StagedCount==0);d.TransferItem(0,1,10);Assert(d.Inventory()[0].Id==DomainEditor.EmptyItemId&&d.Inventory()[1].Quantity==10);w.Undo();d.TransferItem(0,2,6);Assert(d.Inventory()[0].Quantity==4&&d.Inventory()[2].Quantity==10);w.Undo();Assert(w.StagedCount==0);});
        Test("transfer rejects wrong ID oversized same target shortage before staging",()=>{var(w,d)=Open(false);Reject(()=>d.TransferItem(0,2,1));Reject(()=>d.TransferItem(0,0,1));Reject(()=>d.TransferItem(0,1,10000));Reject(()=>d.TransferItem(0,1,0));Assert(w.StagedCount==0);var(a,b)=Open();Reject(()=>b.TransferItem(0,2,7));Assert(a.StagedCount==0);});
        Test("three kinds clear restore original positions and exact export",()=>{foreach(int i in new[]{1,2,3}){var(w,d)=Open();var draft=d.ReadEquipmentDraft(i);Assert(draft.Decorations!.SequenceEqual(new uint[]{11,12,0}));d.ApplyEquipmentDraft(draft,[0,12,0],null);Assert(d.DecorationIds(i).SequenceEqual(new uint[]{0,12,0}));ExactExport(w);w.Undo();Assert(w.StagedCount==0);d.ApplyEquipmentDraft(d.ReadEquipmentDraft(i),[0,0,0],null);d.ApplyEquipmentDraft(d.ReadEquipmentDraft(i),[11,12,0],null);Assert(w.StagedCount==0);}});
        Test("draft coupled pairs decoration atomic no-op undo unknown arrays",()=>{foreach(int auxiliary in new[]{4,5}){var(w,d)=Open(auxiliary:auxiliary);var draft=d.ReadEquipmentDraft(3);int depth=w.UndoDepth;d.ApplyEquipmentDraft(draft,draft.Decorations,draft.Pairs);Assert(w.UndoDepth==depth);d.ApplyEquipmentDraft(draft,[0,0,0],[new(5,7),new(2,3)]);Assert(w.UndoDepth==depth+1&&d.Talisman(3).Pairs.SequenceEqual(new SkillPair[]{new(5,7),new(2,3)})&&d.Talisman(3).AuxiliaryArrayCount==auxiliary);ExactExport(w);w.Undo();Assert(w.StagedCount==0);}});
        Test("invalid jewel pair position kind malformed optional section no partial stage",()=>{var(w,d)=Open();var draft=d.ReadEquipmentDraft(3);Reject(()=>d.ApplyEquipmentDraft(draft,[12,11,0],null));Reject(()=>d.ApplyEquipmentDraft(draft,[0,0],null));Reject(()=>d.ApplyEquipmentDraft(draft,[0,0,0],[new(99,99),new(2,3)]));Reject(()=>d.ReadEquipmentDraft(0));Assert(w.StagedCount==0);var(a,b)=Open(decorations:2);var partial=b.ReadEquipmentDraft(3);Assert(partial.Decorations is null&&partial.Pairs is not null);Reject(()=>b.ApplyEquipmentDraft(partial,[0,0,0],null));b.ApplyEquipmentDraft(partial,null,[new(5,7),new(2,3)]);Assert(a.StagedCount>0);});
        Test("stale draft identity and snapshot rejection",()=>{var(w,d)=Open();var draft=d.ReadEquipmentDraft(3);d.SetTalismanPair(3,0,new(5,7));int depth=w.UndoDepth;Reject(()=>d.ApplyEquipmentDraft(draft,[0,0,0],null));Assert(w.UndoDepth==depth);Reject(()=>d.ApplyEquipmentDraft(d.ReadEquipmentDraft(3) with{Id=999},[0,0,0],null));});
        Test("provider search all languages numeric and category respect gate",()=>{var names=new CatalogProviderNames();names.SetProvider(new LocalGameCatalogProvider(new GameCatalog([new(GameCatalogKind.Weapon,100,new(){["en"]="Synthetic blade",["zh-CN"]="合成刀"},EquipmentKind:1,Category:"Synthetic category",Origin:new("synthetic","synthetic"))])));Assert(!names.Matches(GameCatalogKind.Weapon,100,"合成",1)&&names.Category(GameCatalogKind.Weapon,100,1) is null&&names.Matches(GameCatalogKind.Weapon,100,"0x00000064",1));names.ShowUnverifiedCandidates=true;Assert(names.Matches(GameCatalogKind.Weapon,100,"合成",1)&&names.Matches(GameCatalogKind.Weapon,100,"blade",1)&&names.Category(GameCatalogKind.Weapon,100,1)=="Synthetic category");});
        File.WriteAllText("test-results-r9.json",JsonSerializer.Serialize(new{executedAtUtc=DateTimeOffset.UtcNow,scope="Synthetic only; no game acceptance",failures,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R9 groups={results.Count}; failures={failures}");return failures==0?0:1;
    }
}
